% Include necessary library
include "globals.mzn";

% We have 5 rows (unnamed persons). Each row has a child name, age, country, and story.
set of int: INDEX = 1..5;

% Real ages for index mapping: 1→3, 2→5, 3→7, 4→8, 5→10
array[INDEX] of int: ageVal = [3,5,7,8,10];

% Indexing conventions:
%   Children:      1=Bernice, 2=Carl,    3=Debby,   4=Sammy,   5=Ted
%   Countries:     1=Ethiopia, 2=Kazakhstan, 3=Lithuania, 4=Morocco, 5=Yemen
%   Stories:       1=burning bush, 2=captivity, 3=Moses’s youth, 4=Passover, 5=Ten Commandments

% Decision variables: for each row r, we pick one child, one age‐index, one country, one story
array[INDEX] of var INDEX: children;   % children[r] = child index at row r
array[INDEX] of var INDEX: ages;       % ages[r]     = age‐index at row r
array[INDEX] of var INDEX: countries;  % countries[r]= country‐index at row r
array[INDEX] of var INDEX: stories;    % stories[r]  = story‐index at row r

% All must be permutations
constraint all_different(children);
constraint all_different(ages);
constraint all_different(countries);
constraint all_different(stories);

% Build inverse maps to locate rows quickly by attribute
array[INDEX] of var INDEX: posChild;   % posChild[c] = row where children[row]=c
array[INDEX] of var INDEX: posCountry; % posCountry[k] = row where countries[row]=k
array[INDEX] of var INDEX: posStory;   % posStory[s] = row where stories[row]=s

constraint inverse(children,   posChild);
constraint inverse(countries, posCountry);
constraint inverse(stories,   posStory);

% 1. Debby’s family is from Lithuania.
%    Debby index=3, Lithuania index=3
constraint posChild[3] = posCountry[3];

% 2. The child who told Passover (story=4) is two years older than Bernice (child=1).
constraint ageVal[ages[posStory[4]]] = ageVal[ages[posChild[1]]] + 2;

% 3. The child from Yemen (country=5) is younger than the child from Ethiopia (country=1).
constraint ageVal[ages[posCountry[5]]] < ageVal[ages[posCountry[1]]];

% 4. The child from Morocco (country=4) is three years older than Ted (child=5).
constraint ageVal[ages[posCountry[4]]] = ageVal[ages[posChild[5]]] + 3;

% 5. Sammy (child=4) is three years older than the child who told Moses’s youth (story=3).
constraint ageVal[ages[posChild[4]]] = ageVal[ages[posStory[3]]] + 3;

solve satisfy;

% Output in JSON with parallel arrays; row i gives one child's data, where
% children[i] is the child index, ages[i] the age‐index, etc.
output [
  "{",
    "\"ages\":["     ++ join(",", [show(ages[i])     | i in INDEX]) ++ "],",
    "\"children\":[" ++ join(",", [show(children[i]) | i in INDEX]) ++ "],",
    "\"countries\":["++ join(",", [show(countries[i])| i in INDEX]) ++ "],",
    "\"stories\":["  ++ join(",", [show(stories[i])  | i in INDEX]) ++ "]",
  "}"
];
```

