% Include global constraints library
include "globals.mzn";

% Number of cities
int: n = 12;

% Coordinates of each city
array[1..n] of int: x = [288, 288, 270, 256, 256, 246, 236, 228, 228, 220, 212, 204];
array[1..n] of int: y = [149, 129, 133, 141, 163, 157, 169, 169, 148, 164, 172, 159];

% Precompute the distance matrix (rounded Euclidean distances)
array[1..n, 1..n] of int: dist = 
  array2d(1..n, 1..n,
    [ if i = j then 0
      else round(sqrt((x[i] - x[j])^2 + (y[i] - y[j])^2))
      endif
      | i in 1..n, j in 1..n
    ]);

% Decision variables: successor of each city in the tour
array[1..n] of var 1..n: succ;

% Total travel distance to minimize
var int: travel_distance;

% Ensure the chosen successors form a single Hamiltonian circuit
constraint circuit(succ);

% Define the objective as the sum of distances along the circuit
constraint travel_distance = sum(i in 1..n)(dist[i, succ[i]]);

% Solve for the minimum travel distance
solve minimize travel_distance;

% Output the result in JSON format
output [
  "{",
    "\"travel_distance\": " ++ show(travel_distance),
  "}"
];
```

