% Include necessary library
include "globals.mzn";

% Input data
int: n_slots = 9;          % slots on each template
int: n_templates = 2;      % number of templates
int: n_var = 7;            % number of variations
array[1..n_var] of int: demand = [250,255,260,500,500,800,1100];

% Upper bound on sheets printed per template
int: max_prod = sum(demand);

% Decision variables
% production[t] = number of sheets printed using template t
array[1..n_templates] of var 0..max_prod: production;

% layout[t,s] = variation assigned to slot s on template t
array[1..n_templates, 1..n_slots] of var 1..n_var: layout;

% Constraints
% For each variation v, total produced items >= demand[v]
constraint
  forall(v in 1..n_var) (
    sum(t in 1..n_templates, s in 1..n_slots)(
       bool2int(layout[t,s] == v) * production[t]
    ) >= demand[v]
  );

% Objective: minimize total number of sheets printed
solve minimize sum(t in 1..n_templates)(production[t]);

% Output in JSON format
output [
  "{",
    "\"production\": [" ++
      join(",", [ show(production[t]) | t in 1..n_templates ]) ++ "],",
    "\"layout\": [" ++
      join(",", [
        "[" ++ join(",", [ show(layout[t,s]) | s in 1..n_slots ]) ++ "]"
        | t in 1..n_templates
      ]) ++ "]",
  "}"
];
