% Include the global constraints library
include "globals.mzn";

% Number of marks on the Golomb ruler
int: size = 10;

% A safe upper bound on the length of the ruler
int: max_length = size * size;

% Decision variables: positions of the marks
array[1..size] of var 0..max_length: marks;

% The first mark is at position 0
constraint marks[1] = 0;

% Marks are strictly increasing
constraint forall(i in 1..size-1)(
    marks[i] < marks[i+1]
);

% Define all pairwise differences
array[1..size, 1..size] of var 1..max_length: diffs;
constraint
    forall(i,j in 1..size where i < j)(
        diffs[i,j] = marks[j] - marks[i]
    );

% All differences must be distinct
constraint all_different([diffs[i,j] | i,j in 1..size where i < j]);

% Symmetry breaking: first difference less than last difference
constraint marks[2] - marks[1] < marks[size] - marks[size-1];

% Objective: minimize the total length of the ruler
var int: length = marks[size];
solve minimize length;

% Output the marks and length in JSON format
output [
    "{",
    "\"marks\": [" ++ join(",", [show(marks[i]) | i in 1..size]) ++ "],",
    "\"length\": " ++ show(length),
    "}"
];
```

