  forall(i in 1..n-1) (
    diffs[i] = abs(x[i+1] - x[i])
  );

% 4) Symmetry breaking: fix first pitch-class to 0 (optional but speeds up solve)
constraint x[1] = 0;
% 5) Break reflection symmetry: enforce an ordering on the first and last interval
constraint diffs[1] < diffs[n-1];

solve satisfy;

