% meet[p,i,k] = true if boats i and k meet (visit same host) in period p
array[1..n_periods, 1..n_boats, 1..n_boats] of var bool: meet;

% 1. A boat is a host iff it "visits" itself in all periods
constraint
  forall(p in 1..n_periods, i in 1..n_boats) (
    (visits[p,i] = i) <-> is_host[i]
  );

% 2. Every visit must be to a designated host
constraint
  forall(p in 1..n_periods, i in 1..n_boats) (
    is_host[visits[p,i]]
  );

% 3. Capacity constraints: total people aboard boat j in period p
constraint
  forall(p in 1..n_periods, j in 1..n_boats) (
    sum(i in 1..n_boats)(
      crew_size[i] * bool2int(visits[p,i] = j)
    )
    <= capacity[j]
  );

% 4. A guest boat cannot revisit the same host
constraint
  forall(i in 1..n_boats, p1, p2 in 1..n_periods where p1 < p2) (
    visits[p1,i] != visits[p2,i]
  );

% 5. Define meeting indicators
constraint
  forall(p in 1..n_periods, i, k in 1..n_boats where i < k) (
    (visits[p,i] = visits[p,k]) <-> meet[p,i,k]
  );

% 6. Any two guest crews meet at most once
constraint
  forall(i, k in 1..n_boats where i < k) (
    sum(p in 1..n_periods)( bool2int(meet[p,i,k]) ) <= 1
  );

% Objective: minimize the number of hosts
var int: num_hosts = sum(i in 1..n_boats)( bool2int(is_host[i]) );
solve minimize num_hosts;

% Output in JSON format
output [
  "{",
    "\"visits\": [" ++
      join(",", [
        "[" ++ join(",", [ show(visits[p,i]) | i in 1..n_boats ]) ++ "]"
      | p in 1..n_periods ]) ++ "],",
    "\"is_host\": [" ++
      join(",", [ show(bool2int(is_host[i])) | i in 1..n_boats ]) ++ "]",
  "}"
];
```

