% Double Round-Robin Tournament Scheduler
% Schedules n_teams teams over 2*(n_teams-1) rounds,
% using the circle method and swapping home/away in the second half.

int: n_teams = 8; 
constraint n_teams mod 2 = 0;  % number of teams must be even

int: N = n_teams;
int: R = N - 1;              % number of rounds per single round-robin
int: M = N div 2;            % matches per round

% First half schedules: home1[r,m], away1[r,m] for r in 1..R, m in 1..M
array[1..R, 1..M] of var 1..N: home1;
array[1..R, 1..M] of var 1..N: away1;

% Generate first half by circle method
% Match 1 pairs fixed team N with rotating opponents
constraint
  forall(r in 1..R) (
    let { int: opp = if r mod R != 0 then r mod R else R } in
    home1[r,1] = if r mod 2 = 1 then N else opp /\
    away1[r,1] = if r mod 2 = 1 then opp else N
  );

% Other matches by rotating the remaining N-1 teams
constraint
  forall(r in 1..R, m in 2..M) (
    let {
      int: t1 = ((r + m - 2) mod R) + 1,
      int: t2 = ((r - m + R) mod R) + 1
    } in
    home1[r,m] = if m mod 2 = 1 then t1 else t2 /\
    away1[r,m] = if m mod 2 = 1 then t2 else t1
  );

% Full schedule: double round-robin with swapped home/away in second half
array[1..2*R, 1..M] of var 1..N: home;
array[1..2*R, 1..M] of var 1..N: away;

constraint
  forall(r in 1..R, m in 1..M) (
    home[r,m] = home1[r,m] /\
    away[r,m] = away1[r,m]
  ) /\
  forall(r in R+1..2*R, m in 1..M) (
    home[r,m] = away1[r-R,m] /\
    away[r,m] = home1[r-R,m]
  );

solve satisfy;

output [
  "{",
  "\"home\": [" ++
    join(
      ",",
      [ "[" ++ join(",", [show(home[r,m]) | m in 1..M]) ++ "]"
        | r in 1..2*R ]
    )
  ++ "],",
  "\"away\": [" ++
    join(
      ",",
      [ "[" ++ join(",", [show(away[r,m]) | m in 1..M]) ++ "]"
        | r in 1..2*R ]
    )
  ++ "]",
  "}"
];
```

