% Input data
int: n = 9;                           % Order of the Steiner Triple System
int: m = n * (n - 1) div 6;           % Number of triples

% Decision Variables
% sets[t, 1..3] is the t-th triple, stored in ascending order
array[1..m, 1..3] of var 1..n: sets;

% Constraints

% 1) Each triple consists of 3 distinct elements in ascending order
constraint
  forall(t in 1..m) (
    sets[t,1] < sets[t,2]
    /\ sets[t,2] < sets[t,3]
  );

% 2) Every pair of elements i < j occurs in exactly one triple
constraint
  forall(i, j in 1..n where i < j) (
    sum(t in 1..m)(
      bool2int(
        (sets[t,1] == i \/ sets[t,2] == i \/ sets[t,3] == i)
        /\
        (sets[t,1] == j \/ sets[t,2] == j \/ sets[t,3] == j)
      )
    ) == 1
  );

% 3) Symmetry-breaking: enforce a lexicographic ordering on the triples
constraint
  forall(t in 1..m-1) (
    lex_less(
      [ sets[t,k]   | k in 1..3 ],
      [ sets[t+1,k] | k in 1..3 ]
    )
  );

solve satisfy;

% Output the solution in JSON format
output [
  "{",
    "\"sets\": [",
      join(",", [
        "[" ++ join(",", [ show(sets[t,k]) | k in 1..3 ]) ++ "]"
        | t in 1..m
      ]),
    "]",
  "}"
];
