% Diamond-free Degree Sequences for N = 10
% Find all simple undirected graphs on N vertices
% with degrees > 0, each degree mod 3 = 0, sum of degrees mod 12 = 0,
% non-increasing degree sequence, and diamond-free.

int: N = 10;

% Adjacency matrix: matrix[i,j] = true if edge (i,j) exists
array[1..N, 1..N] of var bool: matrix;

% Degree of each vertex
array[1..N] of var int: deg;

% No loops
constraint forall(i in 1..N) (
  matrix[i,i] = false
);

% Symmetry for undirected graph
constraint forall(i, j in 1..N where i < j) (
  matrix[i,j] = matrix[j,i]
);

% Compute degrees
constraint forall(i in 1..N) (
  deg[i] = sum(j in 1..N)(
    if matrix[i,j] then 1 else 0 endif
  )
);

% Non-increasing degree sequence
constraint forall(i in 1..N-1) (
  deg[i] >= deg[i+1]
);

% Degrees > 0 and divisible by 3
constraint forall(i in 1..N) (
  deg[i] > 0 /\ deg[i] mod 3 = 0
);

% Sum of degrees mod 12 = 0
constraint sum(i in 1..N)(deg[i]) mod 12 = 0;

% Diamond-free: any 4 vertices have at most 4 edges among them
constraint forall(i, j, k, l in 1..N where i < j /\ j < k /\ k < l) (
  (if matrix[i,j] then 1 else 0 endif
   + if matrix[i,k] then 1 else 0 endif
   + if matrix[i,l] then 1 else 0 endif
   + if matrix[j,k] then 1 else 0 endif
   + if matrix[j,l] then 1 else 0 endif
   + if matrix[k,l] then 1 else 0 endif) <= 4
);

solve satisfy;

% Output the adjacency matrix as JSON
output [
  "{",
    "\"matrix\": [",
    join(
      ",",
      [ "[" ++ join(",", [ show(matrix[i,j]) | j in 1..N ]) ++ "]"
        | i in 1..N
      ]
    ),
    "]",
  "}"
];
