% Decision variables: my age (m) and husband's age (h)
var 1..200: m;
var 1..200: h;

% Permutations of the four operations for each direction
% 1 -> +2, 2 -> /8, 3 -> -3, 4 -> *7
array[1..4] of var 1..4: perm1;
array[1..4] of var 1..4: perm2;

% Both sequences must use each operation exactly once
constraint all_different(perm1);
constraint all_different(perm2);
% And the two orders must differ in at least one position
constraint exists(k in 1..4)(perm1[k] != perm2[k]);

% Intermediate results when applying operations
array[0..4] of var int: res1;  % from m to h
array[0..4] of var int: res2;  % from h to m

% Initial conditions
constraint res1[0] = m;
constraint res2[0] = h;

% Final conditions
constraint res1[4] = h;
constraint res2[4] = m;

% Apply each operation in perm1 to go from m to h
constraint
  forall(i in 1..4)(
    (perm1[i] == 1 -> res1[i] = res1[i-1] + 2) /\
    (perm1[i] == 2 -> (res1[i-1] mod 8 = 0 /\ res1[i] = res1[i-1] div 8)) /\
    (perm1[i] == 3 -> res1[i] = res1[i-1] - 3) /\
    (perm1[i] == 4 -> res1[i] = res1[i-1] * 7)
  );

% Apply each operation in perm2 to go from h back to m
constraint
  forall(i in 1..4)(
    (perm2[i] == 1 -> res2[i] = res2[i-1] + 2) /\
    (perm2[i] == 2 -> (res2[i-1] mod 8 = 0 /\ res2[i] = res2[i-1] div 8)) /\
    (perm2[i] == 3 -> res2[i] = res2[i-1] - 3) /\
    (perm2[i] == 4 -> res2[i] = res2[i-1] * 7)
  );

solve satisfy;

% Output in JSON format
output [
  "{",
  "\"m\": " ++ show(m) ++ ",",
  "\"h\": " ++ show(h),
  "}"
];
