include "globals.mzn";

% Define the range of guests
set of int: GUESTS = 0..5;

% Allowed neighbors for each guest:
% 0=Andrew, 1=Betty, 2=Cara, 3=Dave, 4=Erica, 5=Frank
array[GUESTS] of set of GUESTS: allowed = [
  {3,5},  % Andrew -> Dave, Frank
  {2,4},  % Betty  -> Cara, Erica
  {1,5},  % Cara   -> Betty, Frank
  {0,4},  % Dave   -> Andrew, Erica
  {1,3},  % Erica  -> Betty, Dave
  {0,2}   % Frank  -> Andrew, Cara
];

% Decision variables: seating order around a round table (6 seats)
array[1..6] of var GUESTS: x;

% All seats must be assigned distinct guests
constraint
  all_different(x);

% Compute conflicts on each of the 6 adjacency pairs (round table)
array[1..6] of var 0..1: conflict;
constraint
  forall(i in 1..5) (
    conflict[i] = bool2int(not (x[i+1] in allowed[x[i]]))
  ) /\
  % adjacency between seat 6 and seat 1
  conflict[6] = bool2int(not (x[1] in allowed[x[6]]));

% Total number of conflicts to minimize
var 0..6: total_conflicts = sum(i in 1..6)(conflict[i]);

% Solve: minimize total conflicts
solve minimize total_conflicts;

% Output the seating order as JSON
output [
  "{",
    "\"x\":[" ++ join(",", [show(x[i]) | i in 1..6]) ++ "]",
  "}"
];
