include "globals.mzn";

% Number of dice and faces
int: N = 5;
int: F = 6;
set of int: D = 1..N;
set of int: R = 1..F;

% The directed "beats" relationships for Rock-Paper-Scissors-Lizard-Spock
% Each pair (i,j) means die i should beat die j.
set of tuple(int,int): E = {
  (1,3),(1,4),  % Rock beats Scissors, Lizard
  (2,1),(2,5),  % Paper beats Rock, Spock
  (3,2),(3,4),  % Scissors beats Paper, Lizard
  (4,2),(4,5),  % Lizard beats Paper, Spock
  (5,1),(5,3)   % Spock beats Rock, Scissors
};

% Decision variables: face values for each die
% We choose all faces across all dice to be different to avoid ties.
array[D,R] of var 1..(N*F): die;
constraint all_different([ die[i,r] | i in D, r in R ]);

% Number of winning face‐to‐face comparisons between dice i and j
array[D,D] of var 0..F*F: wins;
constraint
  forall(i,j in D where i < j) (
    wins[i,j] = sum(r in R, s in R)( bool2int(die[i,r] > die[j,s])) / 1 /\
    wins[j,i] = sum(r in R, s in R)( bool2int(die[j,r] > die[i,s])) / 1
  );

% Enforce the tournament E: if (i,j) in E then wins[i,j] > wins[j,i]
constraint
  forall(i,j in D) (
    (i,j) in E -> wins[i,j] > wins[j,i]
  );

solve satisfy;

% Output the dice as a JSON list of lists under key "dice"
output [
  "{",
    "\"dice\": [",
      join(",", [
        "[" ++ join(",", [ show(die[i,r]) | r in R ]) ++ "]"
        | i in D
      ]),
    "]",
  "}"
];
```

