% Include necessary libraries
include "globals.mzn";

% Input data
int: n = 5;

% Decision variables
% row[k], col[k] give the position of the number k in the grid
array[1..n*n] of var 1..n: row;
array[1..n*n] of var 1..n: col;

% x[r,c] is the number placed in cell (r,c)
array[1..n, 1..n] of var 1..n*n: x;

% Constraints

% 1) x is a permutation of 1..n*n (fills the grid)
constraint
  all_different([ x[r,c] | r in 1..n, c in 1..n ]);

% 2) Channeling: x[row[k],col[k]] = k for each k
constraint
  forall(k in 1..n*n) (
    x[row[k], col[k]] = k
  );

% 3) Movement constraints: between k and k+1
constraint
  forall(k in 1..n*n-1) (
    let {
      var int: dr = abs(row[k+1] - row[k]),
      var int: dc = abs(col[k+1] - col[k])
    } in
    (
      % Type I: horizontal or vertical exactly 3 apart
      ( row[k] = row[k+1] /\ dc = 3 )
      \/
      ( col[k] = col[k+1] /\ dr = 3 )
      \/
      % Type II: diagonal exactly 2 apart
      ( dr = 2 /\ dc = 2 )
    )
  );

% Solve: just find any solution
solve satisfy;

% Output the completed grid x as JSON
output [
  "{",
    "\"x\": [",
      join(",",
        [ "[" ++ join(",", [ show(x[r,c]) | c in 1..n ]) ++ "]"
          | r in 1..n
        ]
      ),
    "]",
  "}"
];
```

