include "globals.mzn";

% Input data
int: num_moves = 3;                   % Number of moves allowed
array[1..3] of int: init = [1,0,1];  % Initial coin faces: 1=heads, 0=tails
int: num_coins = length(init);

% Decision variables: which coin to flip on each move (1..num_coins)
array[1..num_moves] of var 1..num_coins: steps;

% State of coins after each move (0=tail,1=head)
array[0..num_moves, 1..num_coins] of var 0..1: state;

% Initial state constraint
constraint forall(c in 1..num_coins)(
    state[0,c] = init[c]
);

% Transition: if we flip coin 'steps[m]' at move m, we invert that coin; others stay the same
constraint forall(m in 1..num_moves, c in 1..num_coins)(
    state[m,c] = 
      if steps[m] == c then 
        1 - state[m-1,c] 
      else 
        state[m-1,c]
      endif
);

% Final state must be all heads or all tails
constraint
    (forall(c in 1..num_coins)(state[num_moves,c] = 1))
  \/ (forall(c in 1..num_coins)(state[num_moves,c] = 0));

solve satisfy;

% Output the sequence of flips as JSON: "steps"
output [
    "{",
    "\"steps\": [" ++ join(",", [ show(steps[m]) | m in 1..num_moves ]) ++ "]",
    "}"
];
